def load_library():
    tracks, exts = [], {".mp3",".wav",".ogg",".flac",".aac",".m4a"}
    if not SONGS_DIR.exists(): return tracks
    for f in sorted(SONGS_DIR.iterdir()):
        if f.suffix.lower() not in exts: continue
        meta = {}
        jp = JSON_DIR / f"{f.stem}.json"
        if jp.exists():
            try:
                raw = json.loads(jp.read_text(encoding="utf-8"))
                meta = {k:v for k,v in raw.items() if not k.startswith("_") and v is not None}
            except: pass
        tracks.append({"name":f.stem,"file":f.name,
            "bpm":meta.get("bpm",0),"energia":meta.get("energia",50),
            "key":meta.get("key",""),"duracion_segundos":meta.get("duracion_segundos",0),
            "puede_salir":meta.get("puede_salir"),
            "puede_empezar_mezcla":meta.get("puede_empezar_mezcla"),
            "intro_fin":meta.get("intro_fin"),
            "tiene_voz_inicio":meta.get("tiene_voz_inicio",False)})
    return tracks

CAMELOT = {
    "Ab":"1A","Eb":"2A","Bb":"3A","F":"4A","C":"5A","G":"6A","D":"7A","A":"8A",
    "E":"9A","B":"10A","F#":"11A","Db":"12A",
    "Abm":"1B","Ebm":"2B","Bbm":"3B","Fm":"4B","Cm":"5B","Gm":"6B","Dm":"7B",
    "Am":"8B","Em":"9B","Bm":"10B","F#m":"11B","C#m":"12B",
    "G#":"1A","D#":"2A","A#":"3A","C#":"12A","Gb":"11A",
    "G#m":"1B","D#m":"2B","A#m":"3B","Gbm":"11B",
}

def key_bonus(k1,k2):
    def cam(k): return CAMELOT.get((k or "").strip())
    c1,c2=cam(k1),cam(k2)
    if not c1 or not c2: return 5
    if c1==c2: return 15
    n1,l1=int(c1[:-1]),c1[-1]; n2,l2=int(c2[:-1]),c2[-1]
    if l1==l2 and abs(n1-n2) in (1,11): return 12
    if n1==n2 and l1!=l2: return 10
    if l1==l2 and abs(n1-n2) in (2,10): return 5
    return 0

PHASES=[("warm-up",0.12,50,8),("first-build",0.30,68,10),("first-peak",0.48,88,8),
        ("breakdown",0.58,55,16),("second-build",0.72,75,10),("second-peak",0.88,92,8),("outro",1.00,45,12)]

def get_phase(n,total):
    if total<2: return PHASES[0]
    r=min(1.0,n/max(total,1))
    for p in PHASES:
        if r<=p[1]: return p
    return PHASES[-1]

def score_track(c,cur,phase,ps):
    if c["file"] in ps: return -1
    _,_,te,_=phase
    cb=c.get("bpm",0) or 0; ub=cur.get("bpm",0) or 0
    ce=c.get("energia",50) or 50; ue=cur.get("energia",50) or 50
    s=0.0
    if cb and ub:
        d=abs(cb-ub)
        s+=35 if d<=3 else max(0.,35-d*2.5) if d<=14 else max(0.,5-(d-14)*0.5)
    else: s+=10
    s+=max(0.,30-abs(ce-te)*1.1)
    j=abs(ce-ue); s+=(-5 if j>35 else max(0.,15-j*0.43))
    s+=key_bonus(cur.get("key",""),c.get("key",""))
    s+=random.gauss(0,4)
    return max(0.,s)

def pick_next(lib,cur,ps,n):
    phase=get_phase(n,len(lib))
    scored=[(t,score_track(t,cur,phase,ps)) for t in lib]
    cands=[(t,s) for t,s in scored if s>=0]
    if not cands:
        ps2={cur["file"]}
        cands=[(t,score_track(t,cur,phase,ps2)) for t in lib if t["file"]!=cur["file"]]
        cands=[(t,s) for t,s in cands if s>=0]
    if not cands: return None,0,phase
    cands.sort(key=lambda x:x[1],reverse=True)
    top=cands[:min(3,len(cands))]; tw=sum(s for _,s in top) or 1
    r,acc=random.random()*tw,0; chosen=top[0][0]
    for t,s in top:
        acc+=s
        if r<=acc: chosen=t; break
    return chosen,cands[0][1],phase

def build_plan(cur,nxt,ct,phase):
    dur=float(cur.get("duracion_segundos") or 0)
    ps=cur.get("puede_salir")
    e1=cur.get("energia",50) or 50; e2=nxt.get("energia",50) or 50
    b1=cur.get("bpm",0) or 0; b2=nxt.get("bpm",0) or 0
    diff=abs(e2-e1); bd=abs(b1-b2); ph=phase[0]
    if bd<=3 and diff<=12 and b1>=115: style="progressive"
    elif ph=="breakdown": style="avicii"
    elif b1<110 and e1<65: style="avicii"
    elif diff>22: style="avicii"
    elif e1<60 and b1<125: style="avicii"
    elif ph in ("first-peak","second-peak") and e1>=75 and b1>=120: style="guetta"
    elif b1>=125 and e1>=75: style="guetta"
    else: style="guetta"
    if style=="progressive": cf=20. if abs(diff)<=8 else (18. if diff>8 else 16.)
    elif style=="avicii":
        cf=(22. if ph=="breakdown" else 18. if diff<-15 else 16. if diff>15 else 14. if abs(diff)<=8 else 15.)
    else:
        _,_,_,base=phase
        cf=(18. if ph=="breakdown" else 9. if ph in ("first-peak","second-peak") and diff>10
            else 14. if diff<-15 else 11. if diff>15 else float(base)-1 if abs(diff)<=8 else float(base))
    ex=float(ps) if ps else (dur-2. if dur else ct+90)
    sm=max(ex-cf, dur*0.73 if dur else ct+10, ct+8)
    pem=nxt.get("puede_empezar_mezcla"); inf=nxt.get("intro_fin"); tv=nxt.get("tiene_voz_inicio",False)
    if pem is not None: ea=float(pem)
    elif inf is not None and inf>=3.: ea=max(0.,inf-(60./b2*4 if b2>0 else 4.))
    elif tv: ea=4.
    else: ea=0.
    return {"start_current_time":round(sm,2),"start_next_time":round(ea,2),
            "mix_duration":cf,"exit_at":round(ex,2),"phase":ph,"style":style}

LIBRARY = load_library()

class Handler(BaseHTTPRequestHandler):
    def log_message(self,*a): pass
    def do_GET(self):
        p=urllib.parse.urlparse(self.path); qs=urllib.parse.parse_qs(p.query)
        if p.path in ("/","/index.html"):
            self.ok(HTML.encode("utf-8"),"text/html")
        elif p.path=="/api/library":
            self.ok(json.dumps(LIBRARY).encode(),"application/json")
        elif p.path=="/api/next":
            cf=qs.get("current",[None])[0]; ct=float(qs.get("time",[0])[0]); n=int(qs.get("count",[0])[0])
            try: ps=set(json.loads(urllib.parse.unquote(qs.get("played",["[]"])[0])))
            except: ps=set()
            cur=next((t for t in LIBRARY if t["file"]==cf),None)
            if not cur: self.ok(b'{"error":"not found"}', "application/json"); return
            nxt,score,phase=pick_next(LIBRARY,cur,ps,n)
            if not nxt: self.ok(b'{"error":"no tracks"}', "application/json"); return
            plan=build_plan(cur,nxt,ct,phase)
            self.ok(json.dumps({"track":nxt,"plan":plan,"score":round(score,1),"phase":phase[0]},default=str).encode(),"application/json")
        elif p.path.startswith("/audio/"):
            fname=urllib.parse.unquote(p.path[7:]); fp=SONGS_DIR/fname
            if not fp.exists(): self.send_error(404); return
            mime={".mp3":"audio/mpeg",".wav":"audio/wav",".ogg":"audio/ogg",
                  ".flac":"audio/flac",".aac":"audio/aac",".m4a":"audio/mp4"}.get(fp.suffix.lower(),"audio/mpeg")
            data=fp.read_bytes()
            self.send_response(200); self.send_header("Content-Type",mime)
            self.send_header("Content-Length",len(data)); self.end_headers(); self.wfile.write(data)
        else: self.send_error(404)
    def ok(self,data,ct):
        self.send_response(200); self.send_header("Content-Type",f"{ct}; charset=utf-8")
        self.send_header("Content-Length",len(data)); self.end_headers(); self.wfile.write(data)


